"""Hand check of the GoEmotions GROUPS (negative / positive / ambiguous). Blind, shuffled label page; tick all that apply (a comment can carry several groups); 'neutral or none' excludes the others.
Sample from ALL documents (149,815, r/StopEatingSeedOils) in two periods (before 2024; from Aug 2024). Strata by what the model says (a group counts at score >= 0.5): negative only, positive only, ambiguous only, none, and mixed (2+ groups); 15 per stratum and period (5 for mixed) = 130 comments. Reader sees the text only (no model output, no period).
Group definitions shown to the reader (GoEmotions taxonomy): negative = anger, annoyance, disappointment, disapproval, disgust, embarrassment, fear, grief, nervousness, remorse, sadness; positive = admiration, amusement, approval, caring, desire, excitement, gratitude, joy, love, optimism, pride, relief; ambiguous = confusion, curiosity, realization, surprise.
Writes (Reddit text: local only) seedoils/data/processed_rebuild_prob/emotion_label_page.html and emotion_label_key.csv (id, stratum, period, model flags), plus emotion_label_population.json (documents per stratum and period, for population weights).
Run from final_project/:  ./.venv-nlp/bin/python seedoils/notebooks/emotion_label_sample.py"""
import html, json
import numpy as np, pandas as pd
R, Rp, P = "seedoils/data/processed_rebuild/", "seedoils/data/processed_rebuild_prob/", "seedoils/data/processed/"
labs = list(pd.read_csv(P + "goemo_monthly.csv", nrows=1).columns[1:29]); g = np.load(R + "goemo_seso.npz", allow_pickle=True); pr = g["p"].astype(np.float32); ids = g["id"]
GR = {"neg": "anger annoyance disappointment disapproval disgust embarrassment fear grief nervousness remorse sadness".split(), "pos": "admiration amusement approval caring desire excitement gratitude joy love optimism pride relief".split(), "amb": "confusion curiosity realization surprise".split()}
Fl = {k: (pr[:, [labs.index(l) for l in ls]] >= 0.5).any(1) for k, ls in GR.items()}; ng = sum(Fl[k].astype(int) for k in Fl)
D = pd.read_csv(R + "seso_docs.csv.gz", usecols=["id", "created_utc", "text"], keep_default_na=False).set_index("id").loc[ids].reset_index(); t = pd.to_datetime(D.created_utc, unit="s")
D["period"] = np.where(t < "2024-01-01", "before 2024", np.where(t >= "2024-08-01", "from Aug 2024", "skip")); D["neg"], D["pos"], D["amb"] = Fl["neg"], Fl["pos"], Fl["amb"]
D["stratum"] = np.select([ng >= 2, (ng == 1) & Fl["neg"], (ng == 1) & Fl["pos"], (ng == 1) & Fl["amb"], ng == 0], ["mixed", "negative", "positive", "ambiguous", "none"], "x")
D = D[D.period != "skip"]; pop = {f"{s}|{p}": int(n) for (s, p), n in D.groupby(["stratum", "period"]).size().items()}; json.dump(pop, open(Rp + "emotion_label_population.json", "w"), indent=1)
rows = []
for (s, p), d in D.groupby(["stratum", "period"]): rows.append(d.sample(5 if s == "mixed" else 15, random_state=3))
S = pd.concat(rows).sample(frac=1, random_state=4).reset_index(drop=True); S[["id", "stratum", "period", "neg", "pos", "amb"]].to_csv(Rp + "emotion_label_key.csv", index=False)
cards = "".join(f'<div class="c" data-id="{r.id}"><p><b>{i + 1}.</b> {html.escape(r.text[:900])}{"..." if len(r.text) > 900 else ""}</p>'
                f'<label><input type="checkbox" class="e" value="neg"> negative emotion</label> <label><input type="checkbox" class="e" value="pos"> positive emotion</label> <label><input type="checkbox" class="e" value="amb"> ambiguous (curious, confused, surprised, realization)</label> <label><input type="checkbox" class="n" value="neu"> neutral or none</label> <input class="note" placeholder="note (optional)"></div>' for i, r in S.iterrows())
page = f"""<!doctype html><meta charset="utf-8"><title>Emotion groups: hand check</title><style>body{{font:15px system-ui;max-width:800px;margin:20px auto;padding:0 16px}}.c{{border:1px solid #ccc;border-radius:6px;padding:10px 14px;margin:12px 0}}p{{margin:6px 0 10px}}label{{margin-right:12px;display:inline-block}}.note{{width:95%;margin-top:6px}}button{{padding:8px 14px}}details{{margin:10px 0}}</style>
<h2>Which emotions does the comment express?</h2><p>{len(S)} comments, shuffled. Tick <b>all</b> that apply: a comment can express more than one. Tick &quot;neutral or none&quot; if no clear emotion is expressed (it clears the other boxes). Judge the comment's own wording, not the topic.</p>
<details><summary>What the groups mean (GoEmotions)</summary><p><b>Negative:</b> anger, annoyance, disappointment, disapproval, disgust, embarrassment, fear, grief, nervousness, remorse, sadness.<br><b>Positive:</b> admiration, amusement, approval, caring, desire, excitement, gratitude, joy, love, optimism, pride, relief.<br><b>Ambiguous:</b> confusion, curiosity, realization, surprise.</p></details>{cards}
<button onclick="dl()">Download answers (CSV)</button><script>document.querySelectorAll('.c').forEach(c=>{{c.querySelector('.n').addEventListener('change',e=>{{if(e.target.checked)c.querySelectorAll('.e').forEach(x=>x.checked=false)}});c.querySelectorAll('.e').forEach(x=>x.addEventListener('change',e=>{{if(e.target.checked)c.querySelector('.n').checked=false}}))}});
function dl(){{let o=['id,neg,pos,amb,neutral,note'];document.querySelectorAll('.c').forEach(c=>{{let v=k=>c.querySelector('input[value='+k+']').checked?1:0;let note=c.querySelector('.note').value.replace(/[,\\n"]/g,' ');o.push([c.dataset.id,v('neg'),v('pos'),v('amb'),v('neu'),note].join(','))}});let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([o.join('\\n')],{{type:'text/csv'}}));a.download='emotion_label_answers.csv';a.click()}}</script>"""
open(Rp + "emotion_label_page.html", "w", encoding="utf-8").write(page); print(len(S), "comments;", S.groupby(["stratum", "period"]).size().to_dict()); print("population:", pop)
